### File Discovery

The original uses `dirFiles` recursively:
```js
function dirFiles (dir, callback, acc) {
  fs.readdir(dir, (err, files) => {
    if (err) throw err;
    acc.remaining += files.length;
    files.forEach(file => {
      let name = path.join(dir, file);
      fs.stat(name, (err, stats) => {
        if (err) { skip; done; }
        else if (ignores.shouldIgnore(name)) { done; }
        else if (stats.isDirectory()) dirFiles(name + '/', ...);
        else { acc.files.push(name); done; }
      });
    });
    done();
  });
}
```

