//!
//! This mirrors the behaviour of `src/argsParser.js` so that command-line
//! invocations behave identically to the original JavaScript implementation.

use serde_json::Value;
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub struct OptionSpec {
    pub key: String,
    pub full: String,
    pub abbr: Option<char>,
    pub flag: bool,
    pub default: Option<Value>,
    pub choices: Option<Vec<Value>>,
    pub help: Option<String>,
    pub metavar: Option<String>,
    pub list: bool,
    pub callback: bool,
    pub process: bool,
    pub display_index: i32,
    pub default_help: Option<String>,
    pub required: bool,
}

#[derive(Debug, Clone, Default)]
pub struct ParsedArgs {
    pub positional: Vec<Value>,
    pub options: serde_json::Map<String, Value>,
}

pub struct OptionSchema {
    pub options: BTreeMap<String, OptionSpec>,
    pub prepared: BTreeMap<String, OptionSpec>,
}

impl OptionSchema {
    pub fn new(raw: Vec<(&str, OptionSpecBuilder)>) -> Self {
        let mut options = BTreeMap::new();
        for (name, builder) in raw {
            let mut spec = builder.build(name.to_string());
            spec.key = name.to_string();
            options.insert(name.to_string(), spec);
        }

        // Help option is injected first (matches JS behaviour).
        let help = OptionSpec {
            key: "help".to_string(),
            full: "help".to_string(),
            abbr: Some('h'),
            flag: true,
            default: None,
            choices: None,
            help: Some("print this help and exit".to_string()),
            metavar: None,
            list: false,
            callback: true,
            process: false,
            display_index: 5,
            default_help: None,
            required: false,
        };
        options.insert("help".to_string(), help);

        let mut prepared = BTreeMap::new();
        for (name, opt) in options.iter() {
            let full = opt.full.clone();
            prepared.insert(format!("--{}", full), opt.clone());
            if let Some(a) = opt.abbr {
                prepared.insert(format!("-{}", a), opt.clone());
            }
            if opt.flag {
                prepared.insert(format!("--no-{}", full), opt.clone());
            }
            // Allow declaration key as well (positional name).
        }
        OptionSchema { options, prepared }
    }

    pub fn help_text(&self) -> String {
        let mut entries: Vec<&OptionSpec> = self.options.values().collect();
        entries.sort_by_key(|o| o.display_index);

        let formatted: Vec<String> = entries.iter().map(|o| format_option(o)).collect();

        let text = format!(
            r#"Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
"..." behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{}"#,
            formatted.join("\n")
        );
        text.trim_start().to_string()
    }
}

pub struct OptionSpecBuilder {
    full: Option<String>,
    abbr: Option<char>,
    flag: bool,
    default: Option<Value>,
    choices: Option<Vec<Value>>,
    help: Option<String>,
    metavar: Option<String>,
    list: bool,
    callback: Option<String>,
    process: bool,
    display_index: i32,
    default_help: Option<String>,
    required: bool,
}

impl OptionSpecBuilder {
    pub fn new() -> Self {
        OptionSpecBuilder {
            full: None,
            abbr: None,
            flag: false,
            default: None,
            choices: None,
            help: None,
            metavar: None,
            list: false,
            callback: None,
            process: false,
            display_index: 0,
            default_help: None,
            required: false,
        }
    }

    pub fn full(mut self, v: &str) -> Self {
        self.full = Some(v.to_string());
        self
    }
    pub fn abbr(mut self, v: char) -> Self {
        self.abbr = Some(v);
        self
    }
    pub fn flag(mut self, v: bool) -> Self {
        self.flag = v;
        self
    }
    pub fn default(mut self, v: impl Into<Value>) -> Self {
        self.default = Some(v.into());
        self
    }
    pub fn default_help(mut self, v: &str) -> Self {
        self.default_help = Some(v.to_string());
        self
    }
    pub fn choices(mut self, v: Vec<&str>) -> Self {
        self.choices = Some(v.into_iter().map(|s| Value::String(s.to_string())).collect());
        self
    }
    pub fn help(mut self, v: &str) -> Self {
        self.help = Some(v.to_string());
        self
    }
    pub fn metavar(mut self, v: &str) -> Self {
        self.metavar = Some(v.to_string());
        self
    }
    pub fn list(mut self, v: bool) -> Self {
        self.list = v;
        self
    }
    pub fn callback(mut self, v: &str) -> Self {
        self.callback = Some(v.to_string());
        self
    }
    pub fn process(mut self, v: bool) -> Self {
        self.process = v;
        self
    }
    pub fn display_index(mut self, v: i32) -> Self {
        self.display_index = v;
        self
    }
    pub fn required(mut self, v: bool) -> Self {
        self.required = v;
        self
    }

    fn build(self, key: String) -> OptionSpec {
        OptionSpec {
            key: key.clone(),
            full: self.full.unwrap_or_else(|| key.clone()),
            abbr: self.abbr,
            flag: self.flag,
            default: self.default,
            choices: self.choices,
            help: self.help,
            metavar: self.metavar,
            list: self.list,
            callback: self.callback.is_some(),
            process: self.process,
            display_index: self.display_index,
            default_help: self.default_help,
            required: self.required,
        }
    }
}

fn format_option(option: &OptionSpec) -> String {
    let mut text = String::from("  ");
    if let Some(a) = option.abbr {
        text.push_str(&format!("-{}, ", a));
    } else {
        text.push_str("    ");
    }
    if option.flag {
        text.push_str("--(no-)");
    } else {
        text.push_str("--");
    }
    text.push_str(&option.full);
    if let Some(choices) = &option.choices {
        text.push('=');
        text.push_str(
            &choices
                .iter()
                .map(|c| match c {
                    Value::String(s) => s.clone(),
                    other => other.to_string(),
                })
                .collect::<Vec<_>>()
                .join("|"),
        );
    } else if let Some(mv) = &option.metavar {
        text.push('=');
        text.push_str(mv);
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(h) = &option.help {
            text.push_str(h);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            let default_str = if let Some(dh) = &option.default_help {
                dh.clone()
            } else if let Some(d) = &option.default {
                json_to_string(d)
            } else {
                String::new()
            };
            text.push_str(&format!("(default: {})", default_str));
        }
    }
    text
}

fn json_to_string(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Null => "null".to_string(),
        other => other.to_string(),
    }
}

pub fn parse_args(schema: &OptionSchema, args: &[String]) -> Result<ParsedArgs, ParseError> {
    let missing = Value::String("__MISSING__".to_string());
    let mut parsed: serde_json::Map<String, Value> = serde_json::Map::new();
    let mut positional: Vec<Value> = Vec::new();

    for (name, opt) in schema.options.iter() {
        if let Some(default) = &opt.default {
            parsed.insert(name.clone(), default.clone());
        } else if opt.list {
            parsed.insert(name.clone(), Value::Array(Vec::new()));
        }
    }

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if arg.starts_with('-') {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            let mut option: Option<OptionSpec>;

            if option_name.contains('=') {
                let idx = option_name.find('=').unwrap();
                value = Some(option_name[idx + 1..].to_string());
                option_name = option_name[..idx].to_string();
            }

            if schema.prepared.contains_key(&option_name) {
                let o = schema.prepared.get(&option_name).unwrap().clone();
                option = Some(o);
            } else {
                let real_name = strip_option_prefix(&option_name);
                let is_list = parsed.contains_key(&real_name)
                    && parsed.get(&real_name).map(|v| v.as_bool() != Some(true)).unwrap_or(false);

                let next_is_option = args
                    .get(i + 1)
                    .map(|s| s.starts_with('-'))
                    .unwrap_or(false);

                option = Some(OptionSpec {
                    key: real_name.clone(),
                    full: real_name.clone(),
                    abbr: None,
                    flag: !parsed.contains_key(&real_name) && value.is_none() && next_is_option,
                    default: None,
                    choices: None,
                    help: None,
                    metavar: None,
                    list: is_list,
                    callback: false,
                    process: true,
                    display_index: 0,
                    default_help: None,
                    required: false,
                });

                if is_list {
                    let current = parsed.remove(&real_name).unwrap_or(Value::Null);
                    let new_value = if current.is_boolean() && current.as_bool() == Some(true) {
                        Value::Array(Vec::new())
                    } else if current.is_array() {
                        current
                    } else {
                        Value::Array(vec![current])
                    };
                    parsed.insert(real_name.clone(), new_value);
                }
            }

            let option = option.unwrap();

            if option.callback {
                let help_text = schema.help_text();
                return Err(ParseError::Help(help_text));
            }

            if option.flag {
                let v = if option_name.starts_with("--no-") {
                    Value::Bool(false)
                } else if value.is_some() {
                    Value::Bool(value.as_deref() == Some("1"))
                } else {
                    Value::Bool(true)
                };
                parsed.insert(option.key.clone(), v);
            } else {
                let mut resolved: Option<String> = value;
                if resolved.is_none() && i + 1 < args.len() {
                    let next = &args[i + 1];
                    if !next.starts_with('-') {
                        resolved = Some(next.clone());
                        i += 1;
                    }
                }
                if let Some(raw) = resolved {
                    let processed = if option.process {
                        try_parse_json(&raw).unwrap_or(Value::String(raw))
                    } else {
                        Value::String(raw)
                    };
                    if option.list {
                        let arr = parsed
                            .entry(option.key.clone())
                            .or_insert_with(|| Value::Array(Vec::new()));
                        if let Value::Array(a) = arr {
                            a.push(processed);
                        }
                    } else {
                        parsed.insert(option.key.clone(), processed);
                    }
                } else {
                    parsed.insert(option.key.clone(), missing.clone());
                }
            }
        } else {
            let is_numeric = arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty();
            positional.push(if is_numeric {
                arg.parse::<i64>().map(Value::from).unwrap_or(Value::String(arg.clone()))
            } else {
                Value::String(arg.clone())
            });
        }
        i += 1;
    }

    // Check for missing values
    for (k, v) in parsed.iter() {
        if v == &missing {
            let full = schema
                .options
                .get(k)
                .map(|o| o.full.clone())
                .unwrap_or_else(|| k.clone());
            return Err(ParseError::MissingValue(format!(
                "Missing value: --{} requires a value\n\n---\n\n{}",
                full,
                schema.help_text()
            )));
        }
    }

    // Validate choices
    let mut errors = Vec::new();
    for (name, opt) in schema.options.iter() {
        if let Some(choices) = &opt.choices {
            let v = parsed.get(name);
            let is_in_choices = match v {
                Some(val) => choices.iter().any(|c| c == val),
                None => true,
            };
            if !is_in_choices {
                let choices_str = choices
                    .iter()
                    .map(|c| match c {
                        Value::String(s) => s.clone(),
                        other => other.to_string(),
                    })
                    .collect::<Vec<_>>()
                    .join(",");
                errors.push(format!(
                    "Error: --{} must be one of the values {}",
                    opt.full, choices_str
                ));
            }
        }
    }

    if !errors.is_empty() {
        return Err(ParseError::Validation(format!(
            "{}\n\n---\n\n{}",
            errors.join("\n"),
            schema.help_text()
        )));
    }

    Ok(ParsedArgs {
        positional,
        options: parsed,
    })
}

fn strip_option_prefix(s: &str) -> String {
    let s = s.strip_prefix("--no-").unwrap_or(s);
    let s = s.strip_prefix("--").unwrap_or(s);
    let s = s.strip_prefix('-').unwrap_or(s);
    s.to_string()
}

fn try_parse_json(s: &str) -> Option<Value> {
    serde_json::from_str(s).ok()
}

#[derive(Debug)]
pub enum ParseError {
    Help(String),
    MissingValue(String),
    Validation(String),
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::Help(s) => write!(f, "{}", s),
            ParseError::MissingValue(s) => write!(f, "{}", s),
            ParseError::Validation(s) => write!(f, "{}", s),
        }
    }
}

