//!
//! Mirrors `src/ignoreFiles.js`: patterns are gitignore-style globs handled by
//! `picomatch`. We implement a faithful subset here so external behaviour is
//! unchanged.

use regex::Regex;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone)]
pub struct IgnoreRules {
    matchers: Vec<Regex>,
}

impl IgnoreRules {
    pub fn new() -> Self {
        IgnoreRules { matchers: Vec::new() }
    }

    /// Add ignore patterns from string input.
    pub fn add(&mut self, input: Option<&str>) {
        if let Some(val) = input {
            self.add_pattern(val);
        }
    }

    /// Add ignore patterns from a list of strings.
    pub fn add_list(&mut self, inputs: &[String]) {
        for input in inputs {
            self.add_pattern(input);
        }
    }

    /// Add ignore patterns from a single value.
    pub fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let patterns: Vec<String> = if val.contains('/') {
            if val.ends_with('/') {
                vec![format!("**/{}{}", val, "**"), format!("{}{}", val, "**")]
            } else {
                vec![val.to_string()]
            }
        } else {
            vec![format!("**/{}", val)]
        };
        for p in &patterns {
            if let Ok(r) = glob_to_regex(p, true) {
                self.matchers.push(r);
            }
        }
    }

    /// Add patterns from a file (gitignore-style).
    pub fn add_from_file(&mut self, file: &Path) {
        let Ok(content) = std::fs::read_to_string(file) else {
            return;
        };
        for line in content.lines() {
            self.add_pattern(line);
        }
    }

    /// Returns true if the given path should be ignored.
    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        let normalized = strip_traversal_prefix(path);
        self.matches(path) || (normalized != path && self.matches(&normalized))
    }

    fn matches(&self, path: &str) -> bool {
        for r in &self.matchers {
            if r.is_match(path) {
                return true;
            }
        }
        false
    }

    pub fn is_empty(&self) -> bool {
        self.matchers.is_empty()
    }
}

fn strip_traversal_prefix(path: &str) -> String {
    let re = Regex::new(r"^(?:\.\.?[/\\])+").unwrap();
    re.replace(path, "").to_string()
}

/// Translate a picomatch glob into a regex. Supports `**`, `*`, `?`,
/// `[abc]`, `[!abc]`, `{a,b,c}` and literal characters.
pub fn glob_to_regex(pattern: &str, dot: bool) -> Result<Regex, regex::Error> {
    let mut re = String::from("^");
    let bytes = pattern.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i] as char;
        match c {
            '*' => {
                if i + 1 < bytes.len() && bytes[i + 1] == b'*' {
                    // `**` segment: match anything including `/`.
                    // If `**` is followed by `/`, consume the slash so that the
                    // segment matches zero or more path components.
                    let mut j = i + 2;
                    if j < bytes.len() && bytes[j] == b'/' {
                        j += 1;
                        // `**/` -> match zero or more dirs (including just one).
                        re.push_str("(?:.*/)?");
                        i = j;
                        continue;
                    } else {
                        // bare `**` -> match anything.
                        re.push_str(".*");
                        i += 2;
                        continue;
                    }
                } else {
                    // `*` -> match anything except `/`.
                    re.push_str("[^/]*");
                }
            }
            '?' => re.push('.'),
            '[' => {
                // character class
                let mut j = i + 1;
                let mut body = String::new();
                while j < bytes.len() && bytes[j] != b']' {
                    body.push(bytes[j] as char);
                    j += 1;
                }
                if j >= bytes.len() {
                    re.push_str("\\[");
                } else {
                    if body.starts_with('!') {
                        body = format!("^{}", &body[1..]);
                    }
                    re.push('[');
                    re.push_str(&body);
                    re.push(']');
                    i = j;
                    continue;
                }
            }
            '{' => {
                let mut j = i + 1;
                let mut depth = 1;
                let start = j;
                while j < bytes.len() && depth > 0 {
                    match bytes[j] as char {
                        '{' => depth += 1,
                        '}' => depth -= 1,
                        _ => {}
                    }
                    j += 1;
                }
                let body = &pattern[start..j - 1];
                let alts: Vec<&str> = body.split(',').collect();
                re.push('(');
                for (k, alt) in alts.iter().enumerate() {
                    if k > 0 {
                        re.push('|');
                    }
                    if let Ok(r) = glob_to_regex(alt, dot) {
                        re.push_str(&r.as_str()[1..r.as_str().len() - 1]);
                    }
                }
                re.push(')');
                i = j;
                continue;
            }
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '\\' => {
                re.push('\\');
                re.push(c);
            }
            _ => re.push(c),
        }
        i += 1;
    }
    re.push('$');
    if !dot {
        // Allow dot files to be skipped on the first path segment.
        // (not used currently, but kept for future compatibility)
    }
    Regex::new(&re)
}

/// Resolve a relative path string to a (potentially) absolute path,
/// leaving it unchanged if it is already absolute.
pub fn resolve_path(path: &str, cwd: &Path) -> PathBuf {
    let p = PathBuf::from(path);
    if p.is_absolute() {
        p
    } else {
        cwd.join(p)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_ignore() {
        let mut rules = IgnoreRules::new();
        rules.add_pattern("**/node_modules/**");
        assert!(rules.should_ignore("node_modules/foo/bar.js"));
        assert!(rules.should_ignore("/abs/path/node_modules/foo.js"));
        assert!(!rules.should_ignore("src/index.js"));
    }

    #[test]
    fn test_traversal_prefix() {
        let mut rules = IgnoreRules::new();
        rules.add_pattern("**/node_modules/**");
        assert!(rules.should_ignore("../app/src/node_modules/foo.js"));
    }

    #[test]
    fn test_directory_pattern() {
        let mut rules = IgnoreRules::new();
        rules.add_pattern("dist/");
        assert!(rules.should_ignore("dist/foo.js"));
        assert!(rules.should_ignore("src/dist/foo.js"));
    }
}"}

