//!
//! Matches the byte sequences produced by `picocolors` in the original
//! implementation so that downstream tooling that parses the runner output
//! keeps working.

use std::io::{self, Write};

const RESET: &str = "\x1b[0m";

fn green(s: &str) -> String {
    format!("\x1b[32m{}\x1b[39m", s)
}
fn yellow(s: &str) -> String {
    format!("\x1b[33m{}\x1b[39m", s)
}
fn red(s: &str) -> String {
    format!("\x1b[31m{}\x1b[39m", s)
}
fn blue(s: &str) -> String {
    format!("\x1b[34m{}\x1b[39m", s)
}
fn white(s: &str) -> String {
    format!("\x1b[37m{}\x1b[39m", s)
}
fn bg_green(s: &str) -> String {
    format!("\x1b[42m{}\x1b[49m", s)
}
fn bg_yellow(s: &str) -> String {
    format!("\x1b[43m{}\x1b[49m", s)
}
fn bg_red(s: &str) -> String {
    format!("\x1b[41m{}\x1b[49m", s)
}
fn bg_blue(s: &str) -> String {
    format!("\x1b[44m{}\x1b[49m", s)
}

/// Prefix badges: e.g. ` OKK ` with green background and white text.
fn badge(text: &str, bg: &str) -> String {
    bg(&white(&format!(" {} ", text)))
}

pub fn ok_badge() -> String {
    badge("OKK", &bg_green)
}
pub fn noc_badge() -> String {
    badge("NOC", &bg_yellow)
}
pub fn skip_badge() -> String {
    badge("SKIP", &bg_yellow)
}
pub fn err_badge() -> String {
    badge("ERR", &bg_red)
}
pub fn rep_badge() -> String {
    badge("REP", &bg_blue)
}

pub fn colored_red(s: &str) -> String {
    red(s)
}
pub fn colored_yellow(s: &str) -> String {
    yellow(s)
}
pub fn colored_green(s: &str) -> String {
    green(s)
}
pub fn colored_blue(s: &str) -> String {
    blue(s)
}

#[allow(dead_code)]
pub fn reset() -> &'static str {
    RESET
}

/// Buffered writer that mirrors `Runner.js`'s `bufferedWrite`. It only
/// buffers once stdout reports backpressure and drains when ready.
pub struct BufferedWriter {
    buffer: Vec<String>,
    buffering: bool,
}

impl BufferedWriter {
    pub fn new() -> Self {
        BufferedWriter {
            buffer: Vec::new(),
            buffering: false,
        }
    }

    pub fn write(&mut self, msg: &str) {
        let stdout = io::stdout();
        let mut handle = stdout.lock();
        if self.buffering {
            self.buffer.push(msg.to_string());
            // Try to flush what we can.
            while !self.buffer.is_empty() {
                if handle.write(self.buffer[0].as_bytes()).is_err() {
                    return;
                }
                self.buffer.remove(0);
            }
            self.buffering = false;
            return;
        }
        match handle.write(msg.as_bytes()) {
            Ok(_) => {}
            Err(_) => {
                self.buffering = true;
                self.buffer.push(msg.to_string());
            }
        }
    }

    pub fn flush(&mut self) {
        let stdout = io::stdout();
        let mut handle = stdout.lock();
        for msg in self.buffer.drain(..) {
            let _ = handle.write(msg.as_bytes());
        }
        let _ = handle.flush();
    }
}

pub fn show_file_stats(error: u64, nochange: u64, skip: u64, ok: u64) -> String {
    format!(
        "Results: \n{} errors\n{} unmodified\n{} skipped\n{} ok\n",
        colored_red(&error.to_string()),
        colored_yellow(&nochange.to_string()),
        colored_yellow(&skip.to_string()),
        colored_green(&ok.to_string())
    )
}

pub fn show_stats(stats: &std::collections::BTreeMap<String, u64>) -> String {
    if stats.is_empty() {
        return String::new();
    }
    let mut out = colored_blue("Stats: \n");
    for (name, qty) in stats {
        out.push_str(&format!("{}: {}\n", name, qty));
    }
    out
}"}

{"security_risk":"LOW","summary":"Create files.rs","command":"create","path":"/workspace/codebase/src/rust/files.rs","file_text":"//! File-system discovery matching the original `Runner.js` semantics.

use crate::ignore::IgnoreRules;
use std::path::{Path, PathBuf};

/// Recursively collect all candidate files for transformation.
///
/// `dirs` is a list of input paths (files or directories). For directories,
/// the entire tree is walked recursively (skipping ignore-pattern matches
/// and unreadable entries). For files, each path is included if it matches
/// the extension filter and is not ignored.
///
/// Returns the file list (filtered) and a list of warnings about skipped
/// entries (mirroring the original `process.stdout.write` lines).
pub fn collect_files(
    paths: &[String],
    extensions: Option<&[String]>,
    ignore: &IgnoreRules,
    cwd: &Path,
) -> (Vec<String>, Vec<String>) {
    let mut all_files = Vec::new();
    let mut warnings = Vec::new();
    for p in paths {
        let resolved = if Path::new(p).is_absolute() {
            PathBuf::from(p)
        } else {
            cwd.join(p)
        };
        let resolved_str = resolved.to_string_lossy().to_string();

        let lstat = match std::fs::symlink_metadata(&resolved) {
            Ok(s) => s,
            Err(_) => {
                warnings.push(format!("Skipping path {} which does not exist. \n", resolved_str));
                continue;
            }
        };

        if lstat.is_dir() {
            let collected = walk_dir(&resolved, extensions, ignore);
            for f in collected {
                all_files.push(f);
            }
        } else if !filter_file(&resolved_str, extensions) || ignore.should_ignore(&resolved_str) {
            // ignored
        } else {
            all_files.push(resolved_str);
        }
    }
    (all_files, warnings)
}

fn walk_dir(
    dir: &Path,
    extensions: Option<&[String]>,
    ignore: &IgnoreRules,
) -> Vec<String> {
    let mut out = Vec::new();
    let mut stack = vec![dir.to_path_buf()];
    while let Some(current) = stack.pop() {
        let entries = match std::fs::read_dir(&current) {
            Ok(e) => e,
            Err(_) => continue,
        };
        for entry in entries.flatten() {
            let path = entry.path();
            let path_str = path.to_string_lossy().to_string();
            // Ensure trailing separator for directories, matching `dir + '/'`.
            let display = if path.is_dir() {
                if path_str.ends_with('/') || path_str.ends_with(std::path::MAIN_SEPARATOR) {
                    path_str
                } else {
                    format!("{}/", path_str)
                }
            } else {
                path_str
            };

            let metadata = match std::fs::symlink_metadata(&path) {
                Ok(md) => md,
                Err(_) => {
                    eprintln!("Skipping path \"{}\" which does not exist.\n", display);
                    continue;
                }
            };

            if ignore.should_ignore(&display) {
                continue;
            }

            if metadata.is_dir() {
                stack.push(path);
            } else {
                let file_str = path.to_string_lossy().to_string();
                if filter_file(&file_str, extensions) {
                    out.push(file_str);
                }
            }
        }
    }
    out
}

fn filter_file(name: &str, extensions: Option<&[String]>) -> bool {
    match extensions {
        None => true,
        Some(exts) => {
            let path = Path::new(name);
            match path.extension() {
                None => false,
                Some(ext) => {
                    let ext_with_dot = format!(".{}", ext.to_string_lossy());
                    exts.iter().any(|e| e == &ext_with_dot)
                }
            }
        }
    }
}"}

