//! Mirrors the option definitions from `bin/jscodeshift.js`.

use crate::arg_parser::{parse_args, OptionSchema, OptionSpecBuilder, ParsedArgs, ParseError};
use serde_json::Value;
use std::path::Path;

const DEFAULT_EXTENSIONS_RAW: &str = "js,jsx,mjs,cjs,es6,ts,tsx";

