/// Parsed CLI options for the runner.
pub struct CliOptions {
    pub transform: String,
    pub cpus: Option<usize>,
    pub verbose: u8,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: Vec<String>,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<String>,
    pub fail_on_error: bool,
    pub version: bool,
    pub stdin: bool,
    pub extra: serde_json::Map<String, Value>,
}

impl CliOptions {
    pub fn from_parsed(parsed: &ParsedArgs) -> Self {
        let get_str = |k: &str| -> Option<String> {
            parsed.options.get(k).and_then(|v| match v {
                Value::String(s) => Some(s.clone()),
                _ => None,
            })
        };
        let get_bool = |k: &str| -> bool {
            parsed.options.get(k).and_then(|v| v.as_bool()).unwrap_or(false)
        };
        let get_num = |k: &str| -> Option<f64> {
            parsed.options.get(k).and_then(|v| v.as_f64())
        };

        let transform = get_str("transform").unwrap_or_else(|| "./transform.js".to_string());
        let cpus = get_num("cpus").map(|n| n as usize);
        let verbose = get_num("verbose").map(|n| n as u8).unwrap_or(0);
        let dry = get_bool("dry");
        let print = get_bool("print");
        let babel = parsed
            .options
            .get("babel")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let extensions = get_str("extensions")
            .unwrap_or_default()
            .split(',')
            .map(|s| format!(".{}", s.trim_start_matches('.')))
            .filter(|s| !s.is_empty() && s != ".")
            .collect();
        let ignore_pattern = parsed
            .options
            .get("ignorePattern")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|x| x.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();
        let ignore_config = parsed
            .options
            .get("ignoreConfig")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|x| x.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();
        let gitignore = get_bool("gitignore");
        let run_in_band = get_bool("runInBand");
        let silent = get_bool("silent");
        let parser = get_str("parser").unwrap_or_else(|| "babel".to_string());
        let parser_config = get_str("parserConfig");
        let fail_on_error = get_bool("failOnError");
        let version = get_bool("version");
        let stdin = get_bool("stdin");

        // Collect extra (unknown) options.
        let known: Vec<&str> = vec![
            "transform",
            "cpus",
            "verbose",
            "dry",
            "print",
            "babel",
            "extensions",
            "ignorePattern",
            "ignoreConfig",
            "gitignore",
            "runInBand",
            "silent",
            "parser",
            "parserConfig",
            "failOnError",
            "version",
            "stdin",
            "help",
        ];
        let mut extra = serde_json::Map::new();
        for (k, v) in parsed.options.iter() {
            if !known.contains(&k.as_str()) {
                extra.insert(k.clone(), v.clone());
            }
        }

        CliOptions {
            transform,
            cpus,
            verbose,
            dry,
            print,
            babel,
            extensions,
            ignore_pattern,
            ignore_config,
            gitignore,
            run_in_band,
            silent,
            parser,
            parser_config,
            fail_on_error,
            version,
            stdin,
            extra,
        }
    }
}

pub fn parse_cli(args: &[String]) -> Result<ParsedArgs, ParseError> {
    let schema = build_schema();
    parse_args(&schema, args)
}

pub fn read_stdin_paths() -> Vec<String> {
    use std::io::Read;
    let mut buffer = String::new();
    let _ = std::io::stdin().read_to_string(&mut buffer);
    buffer
        .split('\n')
        .map(|s| s.to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

pub fn version_string() -> String {
    let pkg_version = env!("CARGO_PKG_VERSION");
