{"security_risk":"LOW","summary":"Create worker.rs","command":"create","path":"/workspace/codebase/src/rust/worker.rs","file_text":"//! In-process worker. The "worker" is a Node.js child process executing the
//! `bridge/transform-host.js` bridge. We communicate via line-delimited JSON
//! over stdin/stdout, which is portable across platforms and avoids
//! platform-specific IPC.

use crate::output::BufferedWriter;
use serde::Deserialize;
use serde_json::{json, Value};
use std::io::{BufRead, Write};
use std::path::PathBuf;
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, Mutex};
use std::thread;

#[derive(Debug, Deserialize)]
#[serde(tag = "action")]
enum WorkerMessage {
    #[serde(rename = "status")]
    Status { status: String, msg: String },
    #[serde(rename = "update")]
    Update { name: String, quantity: u64 },
    #[serde(rename = "free")]
    Free,
    #[serde(rename = "report")]
    Report { file: String, msg: String },
    #[serde(rename = "done")]
    Done,
}

pub struct WorkerHandle {
    pub id: usize,
    pub stdin: Option<ChildStdin>,
    pub stdout: Option<ChildStdout>,
    pub child: Option<Child>,
}

impl WorkerHandle {
    pub fn send_files(&mut self, files: Vec<String>, options: &Value) {
        let payload = json!({
            "files": files,
            "options": options,
        });
        if let Some(stdin) = self.stdin.as_mut() {
            let _ = writeln!(stdin, "{}", payload.to_string());
            let _ = stdin.flush();
        }
    }

    pub fn kill(&mut self) {
        if let Some(mut child) = self.child.take() {
            let _ = child.kill();
            let _ = child.wait();
        }
    }
}

pub struct WorkerPool {
    workers: Vec<WorkerHandle>,
    out: Arc<Mutex<BufferedWriter>>,
}

impl WorkerPool {
    pub fn new(
        count: usize,
        transform_path: &str,
        babel: bool,
        bridge_path: PathBuf,
        node_path: PathBuf,
        cwd: PathBuf,
        out: Arc<Mutex<BufferedWriter>>,
    ) -> std::io::Result<Self> {
        let mut workers = Vec::new();
        for i in 0..count {
            let mut cmd = Command::new(&node_path);
            cmd.arg(&bridge_path)
                .arg(transform_path)
                .arg(if babel { "babel" } else { "no-babel" })
                .env("JSCODESHIFT_CWD", &cwd)
                .current_dir(&cwd)
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped());

            let mut child = cmd.spawn()?;
            let stdin = child.stdin.take();
            let stdout = child.stdout.take();
            workers.push(WorkerHandle {
                id: i,
                stdin,
                stdout,
                child: Some(child),
            });
        }
        Ok(WorkerPool { workers, out })
    }

    pub fn spawn_readers(&mut self, tx: Sender<(usize, WorkerMessage)>) {
        for (i, w) in self.workers.iter_mut().enumerate() {
            let stdout = w.stdout.take();
            let tx = tx.clone();
            if let Some(stdout) = stdout {
                thread::spawn(move || {
                    let reader = std::io::BufReader::new(stdout);
                    for line in reader.lines().flatten() {
                        if line.is_empty() {
                            continue;
                        }
                        match serde_json::from_str::<WorkerMessage>(&line) {
                            Ok(msg) => {
                                if tx.send((i, msg)).is_err() {
                                    break;
                                }
                            }
                            Err(e) => {
                                eprintln!("[bridge parse error] {}: {}", e, line);
                            }
                        }
                    }
                    let _ = tx.send((i, WorkerMessage::Done));
                });
            }
        }
    }

    pub fn len(&self) -> usize {
        self.workers.len()
    }

    pub fn is_empty(&self) -> bool {
        self.workers.is_empty()
    }

    pub fn send_to(&mut self, id: usize, files: Vec<String>, options: &Value) {
        if let Some(w) = self.workers.get_mut(id) {
            w.send_files(files, options);
        }
    }

    pub fn kill_all(&mut self) {
        for w in self.workers.iter_mut() {
            w.kill();
        }
    }
}

impl Drop for WorkerPool {
    fn drop(&mut self) {
        self.kill_all();
    }
}

/// Spawn an in-process worker that runs the transform directly inside the
/// current process. This mirrors `Runner.js` when `runInBand` is true: the
/// Worker is required via `require('./Worker')` rather than forked. We
/// implement this by spawning the bridge just like the parallel case, since
/// the bridge encapsulates the same logic and works in any Node context.
pub fn run_in_band(
    files: Vec<String>,
    options: &Value,
    transform_path: &str,
    babel: bool,
    bridge_path: &PathBuf,
    node_path: &PathBuf,
    cwd: &PathBuf,
    out: Arc<Mutex<BufferedWriter>>,
    on_message: impl Fn(WorkerMessage),
) -> std::io::Result<()> {
    let mut cmd = Command::new(node_path);
    cmd.arg(bridge_path)
        .arg(transform_path)
        .arg(if babel { "babel" } else { "no-babel" })
        .env("JSCODESHIFT_CWD", cwd)
        .current_dir(cwd)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());

    let mut child = cmd.spawn()?;
    let mut stdin = child.stdin.take().unwrap();
    let stdout = child.stdout.take().unwrap();

    let payload = json!({
        "files": files,
        "options": options,
    });
    writeln!(stdin, "{}", payload.to_string())?;
    drop(stdin);

    let reader = std::io::BufReader::new(stdout);
    for line in reader.lines().flatten() {
        if line.is_empty() {
            continue;
        }
        match serde_json::from_str::<WorkerMessage>(&line) {
            Ok(msg) => on_message(msg),
            Err(e) => {
                eprintln!("[bridge parse error] {}: {}", e, line);
            }
        }
    }

    let status = child.wait()?;
    if !status.success() {
        let _ = out.lock().unwrap().write(&format!(
            "[error] bridge exited with status {}\n",
            status
        ));
    }
    Ok(())
}

#[allow(dead_code)]
pub fn dummy_receiver() -> Receiver<(usize, WorkerMessage)> {
    let (_tx, rx) = channel();
    rx
}"}

