use crate::cli::CliOptions;
use crate::files::collect_files;
use crate::ignore::IgnoreRules;
use crate::output::{BufferedWriter, RepBadge, ErrBadge, NocBadge, OkBadge, SkipBadge};
use crate::worker::{run_in_band, WorkerMessage, WorkerPool};
use serde_json::{json, Value};
use std::collections::BTreeMap;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::mpsc::channel;
use std::sync::{Arc, Mutex};
use std::time::Instant;

pub struct RunnerResult {
    pub error: u64,
    pub ok: u64,
    pub nochange: u64,
    pub skip: u64,
    pub stats: BTreeMap<String, u64>,
    pub time_elapsed: String,
}

pub struct Runner<'a> {
    pub options: &'a CliOptions,
    pub transform_path: String,
    pub paths: Vec<String>,
    pub cwd: PathBuf,
    pub bridge_path: PathBuf,
    pub node_path: PathBuf,
}

impl<'a> Runner<'a> {
    pub fn run(&self) -> std::io::Result<Option<RunnerResult>> {
        let mut ignore = IgnoreRules::new();

        // Patterns from CLI.
        for p in &self.options.ignore_pattern {
            ignore.add_pattern(p);
        }
        for cfg in &self.options.ignore_config {
            ignore.add_from_file(Path::new(cfg));
        }
        if self.options.gitignore {
            let p = self.cwd.join(".gitignore");
            ignore.add_from_file(&p);
        }

        let out = Arc::new(Mutex::new(BufferedWriter::new()));

        // Optional URL fetch.
        let transform_path = if self.options.transform.starts_with("http") {
            match fetch_url(&self.options.transform) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("{}", ErrBadge(&format!("ERROR downloading transform: {}", e)));
                    return Ok(None);
                }
            }
        } else {
            self.transform_path.clone()
        };

        if !Path::new(&transform_path).exists() {
            let stderr_msg = format!(
                "{} Transform file {} does not exist \n",
                ErrBadge(""),
                transform_path
            );
            let mut o = out.lock().unwrap();
            o.write(&stderr_msg);
            return Ok(None);
        }

        let (files, warnings) = collect_files(
            &self.paths,
            if self.options.extensions.is_empty() {
                None
            } else {
                Some(&self.options.extensions)
            },
            &ignore,
            &self.cwd,
        );

        if !self.options.silent {
            for w in warnings {
                let mut o = out.lock().unwrap();
                o.write(&w);
            }
        }

        if files.is_empty() {
            if !self.options.silent {
                let mut o = out.lock().unwrap();
                o.write("No files selected, nothing to do. \n");
            }
            return Ok(Some(RunnerResult {
                error: 0,
                ok: 0,
                nochange: 0,
                skip: 0,
                stats: BTreeMap::new(),
                time_elapsed: "0.000".to_string(),
            }));
        }

        let start_time = Instant::now();

        let num_files = files.len();
        let cpus = std::thread::available_parallelism()
            .map(|n| n.get().saturating_sub(1).max(1))
            .unwrap_or(1);
        let cpus = match self.options.cpus {
            Some(n) => std::cmp::min(cpus, n.max(1)),
            None => cpus,
        };

        let chunk_size_const = 50;
        let processes = if self.options.run_in_band {
            1
        } else {
            std::cmp::min(num_files, cpus)
        };
        let chunk_size = if processes > 1 {
            std::cmp::min((num_files + processes - 1) / processes, chunk_size_const)
        } else {
            num_files
        };

        let mut file_index = 0usize;
        let chunks: Vec<Vec<String>> = {
            let mut v = Vec::new();
            while file_index < num_files {
                let end = std::cmp::min(file_index + chunk_size, num_files);
                v.push(files[file_index..end].to_vec());
                file_index = end;
            }
            v
        };

        if !self.options.silent {
            let mut o = out.lock().unwrap();
            o.write(&format!("Processing {} files... \n", num_files));
            if !self.options.run_in_band {
                o.write(&format!("Spawning {} workers...\n", processes));
            }
            if self.options.dry {
                o.write("Running in dry mode, no files will be written! \n");
            }
        }

        // Build the options payload sent to workers.
        let mut payload_options = serde_json::Map::new();
        payload_options.insert("parser".to_string(), Value::String(self.options.parser.clone()));
        if let Some(cfg) = &self.options.parser_config {
            payload_options.insert("parserConfig".to_string(), Value::String(cfg.clone()));
        }
        payload_options.insert("dry".to_string(), Value::Bool(self.options.dry));
        payload_options.insert("print".to_string(), Value::Bool(self.options.print));
        payload_options.insert(
            "verbose".to_string(),
            Value::Number(self.options.verbose.into()),
        );
        for (k, v) in &self.options.extra {
            payload_options.insert(k.clone(), v.clone());
        }
        let payload = Value::Object(payload_options);

        // Counters
        let file_counters = Arc::new(Mutex::new(FileCounters::default()));
        let stats_counter = Arc::new(Mutex::new(BTreeMap::<String, u64>::new()));

        if self.options.run_in_band {
            // Use a single worker invocation that consumes all chunks in one shot.
            let all_files: Vec<String> = chunks.into_iter().flatten().collect();
            let counters = file_counters.clone();
            let stats_c = stats_counter.clone();
            let out_for_messages = out.clone();
            let verbose = self.options.verbose;

            run_in_band(
                all_files,
                &payload,
                &transform_path,
                self.options.babel,
                &self.bridge_path,
                &self.node_path,
                &self.cwd,
                out.clone(),
                move |msg| match msg {
                    WorkerMessage::Status { status, msg } => handle_status(
                        &status,
                        &msg,
                        counters.clone(),
                        out_for_messages.clone(),
                        verbose,
                    ),
                    WorkerMessage::Update { name, quantity } => {
                        let mut s = stats_c.lock().unwrap();
                        *s.entry(name).or_insert(0) += quantity;
                    }
                    WorkerMessage::Report { file, msg } => {
                        let mut o = out_for_messages.lock().unwrap();
                        let line = format!("{}{} {}\n", RepBadge(""), file, msg);
                        o.write(&line);
                    }
                    WorkerMessage::Done => {}
                    WorkerMessage::Free => {}
                },
            )?;
        } else {
            let mut pool = WorkerPool::new(
                processes,
                &transform_path,
                self.options.babel,
                self.bridge_path.clone(),
                self.node_path.clone(),
                self.cwd.clone(),
                out.clone(),
            )?;

            let (tx, rx) = channel::<(usize, WorkerMessage)>();
            pool.spawn_readers(tx);

            // Initial dispatch.
            let chunks_iter = chunks.into_iter();
            let mut next_worker = 0usize;
            for chunk in chunks_iter {
                pool.send_to(next_worker, chunk, &payload);
                next_worker = (next_worker + 1) % pool.len();
            }

            // For each "free" we dispatch more.
            let mut files_iter = Vec::<String>::new().into_iter();
            // We already dispatched all chunks above; in this mode we still
            // listen for free messages and respond accordingly, but since the
            // total work is already allocated to workers, we just acknowledge.
            drop(files_iter);

            let pool = Arc::new(Mutex::new(pool));
            let counters = file_counters.clone();
            let stats_c = stats_counter.clone();
            let out_for_messages = out.clone();
            let verbose = self.options.verbose;
            let pool_arc = pool.clone();
            // Track how many workers have reported Done.
            let done_count = Arc::new(Mutex::new(0usize));
            let done_count_clone = done_count.clone();

            // Move receivers
            while let Ok((worker_id, msg)) = rx.recv() {
                match msg {
                    WorkerMessage::Status { status, msg } => {
                        handle_status(
                            &status,
                            &msg,
                            counters.clone(),
                            out_for_messages.clone(),
                            verbose,
                        );
                    }
                    WorkerMessage::Update { name, quantity } => {
                        let mut s = stats_c.lock().unwrap();
                        *s.entry(name).or_insert(0) += quantity;
                    }
                    WorkerMessage::Report { file, msg } => {
                        let mut o = out_for_messages.lock().unwrap();
                        let line = format!("{}{} {}\n", RepBadge(""), file, msg);
                        o.write(&line);
                    }
                    WorkerMessage::Free => {
                        // No more work.
                    }
                    WorkerMessage::Done => {
                        let mut dc = done_count_clone.lock().unwrap();
                        *dc += 1;
                        if *dc >= pool_arc.lock().unwrap().len() {
                            break;
                        }
                    }
                }
                let _ = worker_id; // suppress unused
            }

            // Wait for workers to exit
            let mut p = pool.lock().unwrap();
            p.kill_all();
        }

        let elapsed = start_time.elapsed();
        let time_elapsed = format!("{:.3}", elapsed.as_secs_f64());

        let counters = file_counters.lock().unwrap().clone();
        let stats = stats_counter.lock().unwrap().clone();

        if !self.options.silent {
            let mut o = out.lock().unwrap();
            o.write("All done. \n");
            o.write(&crate::output::show_file_stats(
                counters.error, counters.nochange, counters.skip, counters.ok,
            ));
            o.write(&crate::output::show_stats(&stats));
            o.write(&format!("Time elapsed: {}seconds \n", time_elapsed));
            o.flush();
            if self.options.fail_on_error && counters.error > 0 {
                std::process::exit(1);
            }
        }

        Ok(Some(RunnerResult {
            error: counters.error,
            ok: counters.ok,
            nochange: counters.nochange,
            skip: counters.skip,
            stats,
            time_elapsed,
        }))
    }
}

#[derive(Default, Clone)]
struct FileCounters {
    pub error: u64,
    pub ok: u64,
    pub nochange: u64,
    pub skip: u64,
}

fn handle_status(
    status: &str,
    msg: &str,
    counters: Arc<Mutex<FileCounters>>,
    out: Arc<Mutex<BufferedWriter>>,
    verbose: u8,
) {
    {
        let mut c = counters.lock().unwrap();
        match status {
            "ok" => c.ok += 1,
            "nochange" => c.nochange += 1,
            "skip" => c.skip += 1,
            "error" => c.error += 1,
            _ => {}
        }
    }
    let mut o = out.lock().unwrap();
    let line = match status {
        "ok" => {
            if verbose >= 2 {
                Some(format!("{}{}\n", OkBadge(""), msg))
            } else {
                None
            }
        }
        "nochange" => {
            if verbose >= 1 {
                Some(format!("{}{}\n", NocBadge(""), msg))
            } else {
                None
            }
        }
        "skip" => {
            if verbose >= 1 {
                Some(format!("{}{}\n", SkipBadge(""), msg))
            } else {
                None
            }
        }
        "error" => Some(format!("{}{}\n", ErrBadge(""), msg)),
        _ => None,
    };
    if let Some(s) = line {
        o.write(&s);
    }
}

fn fetch_url(url: &str) -> std::io::Result<String> {
    // Use curl or wget to download; persist to a tmp file and return path.
    let tmpdir = std::env::temp_dir();
    let ext = url.split('?').next().unwrap_or(url);
    let ext = std::path::Path::new(ext)
        .extension()
        .map(|e| format!(".{}", e.to_string_lossy()))
        .unwrap_or_else(|| ".js".to_string());
    let tmpfile = tmpdir.join(format!("jscodeshift-{}", uuid_like_name()));
    let tmpfile_str = tmpfile.to_string_lossy().to_string();

    let status = std::process::Command::new("curl")
        .arg("-sSL")
        .arg(url)
        .arg("-o")
        .arg(&tmpfile_str)
        .status();
    match status {
        Ok(s) if s.success() => Ok(tmpfile_str),
        Ok(s) => Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            format!("curl exited with {}", s),
        )),
        Err(e) => {
            // try wget
            let s = std::process::Command::new("wget")
                .arg("-q")
                .arg(url)
                .arg("-O")
                .arg(&tmpfile_str)
                .status();
            match s {
                Ok(s) if s.success() => Ok(tmpfile_str),
                _ => Err(e),
            }
        }
    }
}

fn uuid_like_name() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let t = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    format!("{}.js", t)
}"}

