        let mut stderr = std::io::stderr();
        let _ = stderr.write_all(
            format!(
                "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
                schema.help_text()
            )
            .as_bytes(),
        );
        std::process::exit(1);
    }

    // Find the transform path.
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let transform_path = if options.transform.starts_with("http") {
        options.transform.clone()
    } else {
