        if p.is_absolute() {
            p.to_string_lossy().to_string()
        } else {
            cwd.join(p).to_string_lossy().to_string()
        }
    };

    // Locate the JS bridge relative to the codebase directory.
    let bridge_path = locate_bridge_path(&cwd);
    let node_path = locate_node_path();

    let runner = runner::Runner {
        options: &options,
        transform_path,
        paths,
        cwd,
        bridge_path,
        node_path,
    };
    if let Err(e) = runner.run() {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

fn locate_bridge_path(cwd: &PathBuf) -> PathBuf {
    // The bridge lives in `<package>/bridge/transform-host.js`. The package
    // directory is the directory containing `package.json` or `Cargo.toml`.
    let mut dir = cwd.clone();
    loop {
        let bridge = dir.join("bridge").join("transform-host.js");
        if bridge.exists() {
            return bridge;
        }
        if !dir.pop() {
            break;
        }
    }
    // Fallback: try resolving alongside the executable.
    if let Ok(exe) = std::env::current_exe() {
        let mut dir = exe.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        while !dir.as_os_str().is_empty() {
            let bridge = dir.join("bridge").join("transform-host.js");
            if bridge.exists() {
                return bridge;
            }
            if !dir.pop() {
                break;
            }
        }
    }
    cwd.join("bridge").join("transform-host.js")
}

fn locate_node_path() -> PathBuf {
    // Allow override via env var.
    if let Ok(p) = std::env::var("JSCODESHIFT_NODE") {
        return PathBuf::from(p);
    }
    // Try `which node`.
    if let Ok(out) = std::process::Command::new("which").arg("node").output() {
        if out.status.success() {
            let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
            if !s.is_empty() {
                return PathBuf::from(s);
            }
        }
    }
    PathBuf::from("node")
}

