  // Worker exits naturally after all transforms complete.
});

async function handle(payload) {
  const files = payload.files || [];
  const options = payload.options || {};
  if (!files.length) {
    emit({ action: 'done' });
    return;
  }
  neoAsync.each(
    files,
    function (file, cb) {
      fs.readFile(file, async function (err, sourceBuf) {
