fn glob_to_regex(pattern: &str, _dot: bool) -> Result<regex::Regex, regex::Error> {
    let mut re = String::from("^");
    let bytes = pattern.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i] as char;
        match c {
            '*' => {
                if i + 1 < bytes.len() && bytes[i + 1] == b'*' {
                    let mut j = i + 2;
                    if j < bytes.len() && bytes[j] == b'/' {
                        j += 1;
                        re.push_str("(?:.*/)?");
                        i = j;
                        continue;
                    } else {
                        re.push_str(".*");
                        i += 2;
                        continue;
                    }
                } else {
                    re.push_str("[^/]*");
                }
            }
