            '[' => { /* ... */ }
            '{' => { /* ... */ }
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '\\' => {
                re.push('\\');
                re.push(c);
            }
            _ => re.push(c),
        }
        i += 1;
    }
    re.push('$');
    regex::Regex::new(&re)
}

