fn read_pkg_dep_version(cwd: &Path, dep: &str) -> String {
    use std::fs;
    let mut dir = cwd.to_path_buf();
    loop {
        let pkg_path = dir.join("package.json");
        if let Ok(content) = fs::read_to_string(&pkg_path) {
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&content) {
                // First check own name (in case the dep's package.json is here)
                if json.get("name").and_then(|n| n.as_str()) == Some(dep) {
                    if let Some(v) = json.get("version").and_then(|n| n.as_str()) {
                        return v.to_string();
                    }
                }
                // Otherwise look up the dependency from this package's deps
                for key in ["dependencies", "devDependencies", "optionalDependencies"] {
                    if let Some(d) = json.get(key).and_then(|m| m.get(dep)) {
                        if let Some(v) = d.as_str() {
                            // Strip semver range (e.g., "^7.0.0" -> "7.0.0")
                            let cleaned = v.trim_start_matches(|c: char| !c.is_ascii_digit());
                            return cleaned.to_string();
                        }
                    }
                }
            }
        }
        if !dir.pop() {
            break;
        }
    }
    String::new()
}"}

